# Lines of code

https://github.com/code-423n4/2024-07-loopfi/blob/main/src/proxy/SwapAction.sol#L137


# Vulnerability details

## Impact
`SwapAction` allows users to do different swaps on different external protocols, this is done by calling `swap`, and passing the following params:
```solidity
struct SwapParams {
    SwapProtocol swapProtocol;
    SwapType swapType;
    address assetIn;
    uint256 amount; // Exact amount in or exact amount out depending on swapType
    uint256 limit; // Min amount out or max amount in depending on swapType
    address recipient;
    uint256 deadline;
    /// @dev `args` can be used for protocol specific parameters
    /// For Balancer, it is the `poolIds` and `assetPath`
    /// For Uniswap v3, it is the `path` for the swap
    bytes args;
}
```
`limit` is used to indicate either the minimum amount out or the maximum amount in, so it's used for slippage in both cases. This is being passed correctly for `BALANCER`, `UNIV3`, and `PENDLE_IN`. However, in the case of `PENDLE_OUT`, `swapParams.amount` is being used instead of `swapParams.limit`, which is wrong.

This forces users to receive fewer tokens than requested as the limit/slippage won't work in the case of a `PENDLE_OUT` swap.

## Proof of Concept

Add the following test in `src/test/integration/PoolAndSwapActionPendle.t.sol`:

```solidity
function test_wrongSlippageAmount() public {
    LimitOrderData memory limitOrderData;
    TokenInput memory tokenInput;
    SwapData memory swapData;

    uint256 amount = 10 ether;
    uint256 minPendleLP = 4.9 ether;
    uint256 minWeETH = 10 ether;

    swapData.swapType = SwapTypePendle.ETH_WETH;
    tokenInput.netTokenIn = amount;
    tokenInput.tokenIn = address(WETH);
    tokenInput.swapData = swapData;

    deal(address(WETH), user, amount);

    vm.startPrank(user);

    WETH.transfer(address(swapAction), amount);

    // User joins Pendle position, while requesting a minimum 4.9e18 Pendle LP
    swapAction.swap(
        SwapParams({
            swapProtocol: SwapProtocol.PENDLE_IN,
            swapType: SwapType.EXACT_IN,
            assetIn: address(0),
            amount: 0,
            limit: minPendleLP,
            recipient: user,
            deadline: 0,
            args: abi.encode(
                market,
                ApproxParams({
                    guessMin: 0,
                    guessMax: 15519288115338392367,
                    guessOffchain: 0,
                    maxIteration: 12,
                    eps: 10000000000000000
                }),
                tokenInput,
                limitOrderData
            )
        })
    );

    // Verify that the user received > 4.9e18
    assertGt(ERC20(market).balanceOf(user), minPendleLP);

    ERC20(market).approve(address(swapAction), type(uint256).max);

    // User exists Pendle position, while requesting a minimum 10e18 weETH
    swapAction.swap(
        SwapParams({
            swapProtocol: SwapProtocol.PENDLE_OUT,
            swapType: SwapType.EXACT_IN,
            assetIn: address(0),
            amount: 0,
            limit: minWeETH,
            recipient: user,
            deadline: 0,
            args: abi.encode(market, ERC20(market).balanceOf(user), weETH)
        })
    );

    // Verify that the user received < 10e18
    assertLt(ERC20(weETH).balanceOf(user), minWeETH);
}
```

## Tools Used

Manual review

## Recommended Mitigation Steps

Use `swapParams.limit` instead of `swapParams.amount` for the `PENDLE_OUT` swap.

```diff
function swap(SwapParams memory swapParams) public payable returns (uint256 retAmount) {
    if (swapParams.swapProtocol == SwapProtocol.BALANCER) {
